-- lovable-cron-fallback-reviewed: preserve existing wake-on-enqueue minute worker, unscheduled by admin_campaign_tick after drain; no permanent new job
ALTER TABLE public.admin_campaigns ADD COLUMN recipient_limit integer NOT NULL DEFAULT 50 CHECK (recipient_limit IN (50,75,100)), ADD COLUMN eligible_total integer NOT NULL DEFAULT 0, ADD COLUMN queued_push integer NOT NULL DEFAULT 0, ADD COLUMN queued_email integer NOT NULL DEFAULT 0;
ALTER TABLE public.admin_campaign_recipients ADD COLUMN dispatch_started_at timestamptz;
CREATE OR REPLACE FUNCTION public.admin_campaign_push_eligible(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id=_user_id AND NOT p.blocked AND COALESCE(p.notification_preferences->>'marketing_push','true')='true' AND COALESCE(p.notification_preferences->>'push_enabled','true')='true' AND EXISTS (SELECT 1 FROM public.push_subscriptions s WHERE s.user_id=p.id AND s.endpoint ~ '^https://' AND length(COALESCE(s.keys->>'auth',''))>0 AND length(COALESCE(s.keys->>'p256dh',''))>0)) $$;
REVOKE ALL ON FUNCTION public.admin_campaign_push_eligible(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.admin_campaign_push_eligible(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.admin_campaign_enqueue(_campaign_id uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c record; n integer; e jsonb; BEGIN
SELECT * INTO c FROM public.admin_campaigns WHERE id=_campaign_id FOR UPDATE;
IF c IS NULL THEN RAISE EXCEPTION 'CAMPAIGN_MISSING'; END IF;
IF c.status <> 'draft' THEN RETURN (SELECT count(*)::integer FROM public.admin_campaign_recipients WHERE campaign_id=_campaign_id); END IF;
IF c.channels ? 'email' THEN RAISE EXCEPTION 'EMAIL_CHANNEL_UNAVAILABLE'; END IF;
IF c.recipient_limit NOT IN (50,75,100) THEN RAISE EXCEPTION 'INVALID_RECIPIENT_LIMIT'; END IF;
e := public.admin_campaign_estimate(c.audience_type,c.audience_filters);
INSERT INTO public.admin_campaign_recipients(campaign_id,user_id,channel) SELECT _campaign_id,a.user_id,'push' FROM public.admin_campaign_audience(c.audience_type,c.audience_filters) a WHERE a.has_push AND public.admin_campaign_push_eligible(a.user_id) AND c.channels ? 'push' ORDER BY a.user_id LIMIT c.recipient_limit ON CONFLICT DO NOTHING;
GET DIAGNOSTICS n=ROW_COUNT;
UPDATE public.admin_campaigns SET eligible_total=COALESCE((e->>'total')::integer,0), estimated_push=(SELECT count(*) FROM public.admin_campaign_audience(c.audience_type,c.audience_filters) a WHERE a.has_push AND public.admin_campaign_push_eligible(a.user_id)), queued_push=n,queued_email=0,status=CASE WHEN n=0 THEN 'completed' ELSE 'queued' END,started_at=now(),completed_at=CASE WHEN n=0 THEN now() END WHERE id=_campaign_id;
IF n>0 THEN PERFORM cron.schedule('admin-campaign-tick','* * * * *','SELECT public.admin_campaign_tick()'); END IF; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.admin_campaign_enqueue(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.admin_campaign_enqueue(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.admin_campaign_claim(_limit integer) RETURNS TABLE(id uuid,campaign_id uuid,user_id uuid,channel text,attempts integer) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
UPDATE public.admin_campaign_recipients r SET status='skipped',error_code='delivery_unknown',updated_at=now() WHERE r.status='processing' AND r.dispatch_started_at IS NOT NULL AND r.updated_at<now()-interval '10 minutes';
RETURN QUERY WITH picked AS (SELECT r.id FROM public.admin_campaign_recipients r JOIN public.admin_campaigns c ON c.id=r.campaign_id AND c.status IN ('queued','sending') WHERE r.status='pending' OR (r.status='processing' AND r.dispatch_started_at IS NULL AND r.updated_at<now()-interval '10 minutes') ORDER BY c.created_at,r.id LIMIT greatest(1,least(_limit,100)) FOR UPDATE OF r SKIP LOCKED) UPDATE public.admin_campaign_recipients r SET status='processing',attempts=r.attempts+1,updated_at=now() FROM picked WHERE r.id=picked.id RETURNING r.id,r.campaign_id,r.user_id,r.channel,r.attempts;
UPDATE public.admin_campaigns c SET status='sending' WHERE c.status='queued' AND EXISTS (SELECT 1 FROM public.admin_campaign_recipients r WHERE r.campaign_id=c.id AND r.status='processing');
PERFORM public.admin_campaign_refresh(c.id) FROM public.admin_campaigns c WHERE c.status IN ('queued','sending'); END $$;
REVOKE ALL ON FUNCTION public.admin_campaign_claim(integer) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.admin_campaign_claim(integer) TO service_role;
CREATE OR REPLACE FUNCTION public.admin_campaign_estimate(_segment text,_filters jsonb) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('total',count(*),'push',count(*) FILTER (WHERE a.has_push AND public.admin_campaign_push_eligible(a.user_id)),'email',count(*) FILTER (WHERE a.has_email AND EXISTS (SELECT 1 FROM public.profiles p WHERE p.id=a.user_id AND btrim(p.email) ~* '^[A-Z0-9.!#$%&''*+/=?^_`{|}~-]+@[A-Z0-9-]+(\.[A-Z0-9-]+)+$'))) FROM public.admin_campaign_audience(_segment,_filters) a $$;
REVOKE ALL ON FUNCTION public.admin_campaign_estimate(text,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.admin_campaign_estimate(text,jsonb) TO service_role;